mapper.select:
SELECT T.* FROM (SELECT O.*, F.PROCESSSTATUS FOLDERSTATUS, F.MONITORPOINTNAME, F.MONITORPOINTNO, P.PROJNO, P.PROJNAME, F.FOLDERNO, F.SAMPLEUSERID, F.SAMPLEUSERNAME FROM T_EMC_ORDER_CHANGE O LEFT JOIN T_EMC_FOLDER_CHANGE F ON F.ID = O.FOLDERID LEFT JOIN T_EMC_PROJECT_CHANGE P ON P.ID = O.PROJID) T
AND EXISTS (SELECT 1 FROM ${targetSampleTable} TAR_ WHERE TAR_.${targetSampleIdColumn} = T.${targetSampleIdColumn}
AND TAR_.${targetSampleCategoryFilterColumn} = #{targetSampleCategoryFilterValue}
AND TAR_.${targetFilterColumn1} = #{targetFilterValue1}
)
AND NOT EXISTS (SELECT 1 FROM ${targetOrderTable} TAR_ WHERE TAR_.${targetOrderColumn} = T.ID
AND TAR_.${targetOrderIdFilterColumn} = #{targetOrderIdFilterValue}
AND TAR_.${targetFilterColumn1} = #{targetFilterValue1}
)
AND NOT EXISTS (SELECT 1 FROM T_EMC_ORDER TAR_ WHERE TAR_.ID = T.ID AND TAR_.SAMPLEID IS NOT NULL)
AND ( T.SAMPLEID IS NULL OR T.SAMPLEID = '')
AND EXISTS (SELECT 1 FROM T_EMC_FOLDER F WHERE T.FOLDERID = F.ID AND F.PROCESSSTATUS = 'done' AND (INSTR( ',' || SAMPLEUSERID || ',',',' || #{sampleUserId} || ',' ) > 0 OR INSTR(',' || SCENEUSERID || ',',',' || #{sceneUserId} || ',' ) > 0) OR INSTR( ',' || PLANSAMPLEUSERID || ',',',' || #{sampleUserId} || ',' ) > 0)
ORDER BY
T.FOLDERID ASC, T.ORDERNO ASC, T.ID DESC

SELECT T.*
  FROM T_EMC_ORDER T
 WHERE T.ID = #{id}
